}

Method.Source:
/// <summary>
///    AVA <c>update</c> method.
/// </summary>
public void AVACheckSmmSalesUnit()
{
    if(    this.RefTableId      == tableNum(smmSalesUnit)
        && this.AVASalesUnitId  != ''                )
    {
        this.RefTableId = tableNum(smmSalesUnit);
        this.RefRecId   = smmSalesUnit::find(this.AVASalesUnitId).RecId;
    }
    else
    {
        this.AVASalesUnitId  = '';
    }
    if(     this.RefTableId     == tableNum(smmSalesUnit)
        &&  this.RefRecId
        &&  this.AVASalesUnitId == '')
    {
        this.AVASalesUnitId = smmSalesUnit::AVAfindRec(this.RefRecId).SalesUnitId;
    }
}

/// <summary>
///    AVA <c>update</c> method.
/// </summary>
public void update()
{
    this.AVACheckSmmSalesUnit();

    next update();
}

/// <summary>
///    AVA <c>insert</c> method.
/// </summary>
public void insert()
{
    this.AVACheckSmmSalesUnit();

    next insert();
}
